var sys_id = current.sys_id;
 var requestedForSysID = current.variables.employee.toString(); 
 var openedBySysID = current.variables.requester.toString();
 var reqItem = new GlideRecord('sc_req_item');
 if (reqItem.get(sys_id)) {
     reqItem.requested_for = requestedForSysID;
     reqItem.opened_by = openedBySysID;
     reqItem.update();
 }

